import { env } from "cloudflare:workers";
import { render, route } from "rwsdk/router";
import { defineApp } from "rwsdk/worker";

import { Document } from "@/app/document";
import { setCommonHeaders } from "@/app/headers";
import { Home } from "@/app/pages/home";

import { drizzle } from "drizzle-orm/d1";
import { lt, eq } from "drizzle-orm";

import { records, type Record as DBRecord } from "@/db/schema";

// ---------------------------------------------------------------------------
// App context: a Drizzle client bound to the D1 binding (env.DB) is attached
// to ctx so HTTP routes can use it. The cron handler, by contrast, builds a
// fresh client off env.DB directly because it runs outside the request cycle.
// ---------------------------------------------------------------------------
export type AppContext = {
  db: ReturnType<typeof drizzle<typeof import("@/db/schema")>>;
};

const app = defineApp([
  setCommonHeaders(),
  (({ ctx }) => {
    ctx.db = drizzle(env.DB, { schema: { records } });
  }) as never,
  render(Document, [route("/", Home)]),
  route("/api/records", {
    // List every record in the database
    get: async ({ ctx }) => {
      const db = (ctx as unknown as AppContext).db;
      const rows = await db.select().from(records).all();
      return Response.json(
        rows.map((r) => ({ id: r.id, label: r.label, expiresAt: r.expiresAt })),
      );
    },
    // Create a record: { "label": string, "expiresAt": number }
    post: async ({ request, ctx }) => {
      const db = (ctx as unknown as AppContext).db;

      let body: { label?: unknown; expiresAt?: unknown };
      try {
        body = (await request.json()) as typeof body;
      } catch {
        return Response.json(
          { error: "Invalid JSON body" },
          { status: 400 },
        );
      }

      const label = typeof body.label === "string" ? body.label : null;
      const expiresAt =
        typeof body.expiresAt === "number" && Number.isFinite(body.expiresAt)
          ? Math.trunc(body.expiresAt)
          : null;

      if (label === null || expiresAt === null) {
        return Response.json(
          { error: "`label` (string) and `expiresAt` (number) are required" },
          { status: 400 },
        );
      }

      const id = crypto.randomUUID();
      const inserted: DBRecord = {
        id,
        label,
        expiresAt,
      };

      await db.insert(records).values(inserted);

      return Response.json(
        { id, label, expiresAt },
        { status: 201 },
      );
    },
  }),
]);

// ---------------------------------------------------------------------------
// Default export: an ExportedHandler that wires the HTTP app to `fetch`
// and adds the cron-triggered cleanup handler to `scheduled`. The cron
// handler builds its own Drizzle client from env.DB because it runs outside
// any HTTP request context.
// ---------------------------------------------------------------------------
export default {
  fetch: app.fetch,
  async scheduled(
    controller: ScheduledController,
    _env: Env,
    _ctx: ExecutionContext,
  ): Promise<void> {
    if (controller.cron !== "0 * * * *") return;

    const db = drizzle(env.DB, { schema: { records } });
    await db.delete(records).where(lt(records.expiresAt, Date.now()));
  },
} satisfies ExportedHandler;

